              "75 \u0448\u0430\u0440\u043E\u0432: \u0431\u0438\u043B\u0435\u0442 5 \u043D\u0430 5. B, I, N, G \u0438 O \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u044B 1\u201315, 16\u201330, 31\u201345, 46\u201360 \u0438 61\u201375. \u0426\u0435\u043D\u0442\u0440 \u0441\u0432\u043E\u0431\u043E\u0434\u0435\u043D. 80 \u0448\u0430\u0440\u043E\u0432 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 4 \u043D\u0430 4 \u0438 \u0441\u0442\u043E\u043B\u0431\u0446\u044B 1\u201320, 21\u201340, 41\u201360 \u0438 61\u201380. \u0414\u043B\u044F \u044D\u0442\u0438\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432 \u043F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0435\u0440\u0438 \u043B\u044E\u0431\u0443\u044E \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C, \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C \u0438\u043B\u0438 \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u044C, \u0447\u0435\u0442\u044B\u0440\u0435 \u0443\u0433\u043B\u0430 \u043B\u0438\u0431\u043E \u0432\u0435\u0441\u044C \u0431\u0438\u043B\u0435\u0442.",
              "90 \u0448\u0430\u0440\u043E\u0432: \u0442\u0440\u0438 \u0441\u0442\u0440\u043E\u043A\u0438 \u0438 \u0434\u0435\u0432\u044F\u0442\u044C \u0441\u0442\u043E\u043B\u0431\u0446\u043E\u0432, \u043F\u044F\u0442\u044C \u0447\u0438\u0441\u0435\u043B \u0432 \u0441\u0442\u0440\u043E\u043A\u0435 \u0438 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0432 \u0431\u0438\u043B\u0435\u0442\u0435. \u0421\u0442\u043E\u043B\u0431\u0446\u044B \u043E\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u044E\u0442 1\u20139, 10\u201319 \u0434\u043E 70\u201379 \u0438 80\u201390; \u0447\u0438\u0441\u043B\u0430 \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u044E\u0442 \u0432\u043D\u0438\u0437. \u041D\u0430 \u043E\u0434\u043D\u043E\u043C \u0431\u0438\u043B\u0435\u0442\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u043D\u0430 \u043E\u0434\u043D\u0443 \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C, \u0434\u0432\u0435 \u0438 \u0432\u0435\u0441\u044C \u0431\u0438\u043B\u0435\u0442. \u0420\u0430\u043D\u043D\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F; \u0432\u0435\u0441\u044C \u0431\u0438\u043B\u0435\u0442 \u0440\u0435\u0448\u0430\u0435\u0442 \u043C\u0430\u0442\u0447."),
            rule_section(:marking, "\u041E\u0442\u043C\u0435\u0442\u043A\u0438 \u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0431\u0438\u043D\u0433\u043E",
              "\u0410\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0436\u0438\u043C \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u0430 \u0438 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u0432\u044B\u0438\u0433\u0440\u044B\u0448. \u0418\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u0448\u0430\u0440\u043E\u0432 3\u201330 \u0441\u0435\u043A\u0443\u043D\u0434, \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u043F\u044F\u0442\u044C. \u0420\u0443\u0447\u043D\u043E\u0439 \u0440\u0435\u0436\u0438\u043C \u0436\u0434\u0451\u0442 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0432\u044B\u0437\u043E\u0432\u0430 \u0432\u0441\u0435\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438. \u041E\u0442\u043C\u0435\u0442\u044C \u043D\u0430\u0437\u0432\u0430\u043D\u043D\u044B\u0435 \u0447\u0438\u0441\u043B\u0430 \u0441\u0432\u043E\u0435\u0433\u043E \u0431\u0438\u043B\u0435\u0442\u0430, \u0437\u0430\u0442\u0435\u043C \u043E\u0431\u044A\u044F\u0432\u0438 \u0431\u0438\u043D\u0433\u043E \u0438\u043B\u0438 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C. \u0417\u0430\u044F\u0432\u043A\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0441\u043A\u043E\u0440\u043E\u0441\u0442\u044C \u0441\u0435\u0442\u0438 \u043D\u0435 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F. \u041E\u0448\u0438\u0431\u043E\u0447\u043D\u0430\u044F \u0437\u0430\u044F\u0432\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442.",
              "\u041F\u043E\u0441\u043B\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u0430 \u044D\u0442\u0430\u043F\u0430 90 \u0448\u0430\u0440\u043E\u0432 \u0432\u0440\u0443\u0447\u043D\u0443\u044E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0438\u0441\u0443\u043D\u043E\u043A \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u044F\u0432\u0438\u0442\u044C \u043F\u0440\u0438 \u0442\u043E\u043C \u0436\u0435 \u0448\u0430\u0440\u0435; \u0438\u043D\u0430\u0447\u0435 \u0441\u043D\u043E\u0432\u0430 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C \u0434\u043B\u044F \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u044F. \u041D\u0430\u0437\u0432\u0430\u043D\u043D\u044B\u0435 \u0447\u0438\u0441\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u043F\u043E\u0437\u0436\u0435. \u041F\u0443\u0441\u0442\u043E\u0439 \u0431\u0430\u0440\u0430\u0431\u0430\u043D \u0431\u0435\u0437 \u0432\u0435\u0440\u043D\u043E\u0439 \u0437\u0430\u044F\u0432\u043A\u0438 \u0434\u0430\u0451\u0442 \u043D\u0438\u0447\u044C\u044E. \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u043F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0448\u0430\u0440\u0430 \u2014 \u0430\u0434\u0430\u043F\u0442\u0430\u0446\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0441\u0442\u0438 Power Games. \u0411\u0438\u043B\u0435\u0442\u044B \u0438 \u0432\u044B\u0437\u043E\u0432\u044B \u043E\u0431\u0441\u043B\u0443\u0436\u0438\u0432\u0430\u0435\u0442 \u043E\u0431\u0449\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440\u043D\u044B\u0439 \u0438\u0441\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C \u0438\u0433\u0440\u044B."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438 \u0447\u0438\u0442\u0430\u044E\u0442 \u0431\u0438\u043B\u0435\u0442. \u0412\u0440\u0443\u0447\u043D\u0443\u044E Enter \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 \u043D\u0430\u0437\u0432\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E, M \u0432\u0432\u043E\u0434\u0438\u0442 \u0447\u0438\u0441\u043B\u043E, B \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442 \u0431\u0438\u043D\u0433\u043E, R \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C. \u041A\u043E\u043C\u0430\u043D\u0434\u044B \u0435\u0441\u0442\u044C \u0438 \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. L \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0448\u0430\u0440, D \u043F\u0440\u043E\u0441\u043C\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0432\u044B\u0437\u043E\u0432\u044B. Tab \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u043B\u044F. F1 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438, Ctrl+F1 \u043F\u0440\u0430\u0432\u0438\u043B\u0430. \u0418\u0441\u0442\u043E\u0440\u0438\u044F, \u0447\u0430\u0442 \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 Power Games.")
          ]
